/bin/bash -lc "python - <<'PY'
import numpy as np, cv2
F=np.load('source_pixels.npz')['rgb']
for name in ['red','blue']:
 print('\\n',name)
 for i in range(96):
  im=F[i]; r,g,b=[im[:,:,k].astype(float) for k in range(3)]
  if name=='red': m=(r>120)&(r>g*1.25)&(r>b*1.15)
  else: m=(b>90)&(b>r*1.2)&(b>g*1.05)
  roi=np.zeros_like(m); roi[40:125,50:215]=1;m=(m&roi).astype('uint8')
  n,l,st,cen=cv2.connectedComponentsWithStats(m)
  cand=[(st[k,4],cen[k]) for k in range(1,n) if st[k,4]>=3]
  cand=sorted(cand,reverse=True,key=lambda x:x[0])
  if i%2==0: print(i+1,[(a,tuple(round(z,1) for z in c)) for a,c in cand[:2]])
PY"
